tape( 'the function returns a function which returns a zero-dimensional ndarray (arraybuffer)', function test( t ) {
	var tensor0d;
	var buf;
	var out;

	tensor0d = factory( 'float32' );

	buf = new ArrayBuffer( 8 );

	out = tensor0d( buf );
	t.strictEqual( isndarrayLikeWithDataType( out, 'float32' ), true, 'returns expected value' );
	t.strictEqual( out.length, 1, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( getData( out ), new Float32Array( buf, 0, 1 ) ), true, 'returns expected value' );

	out = tensor0d( buf, {} );
	t.strictEqual( isndarrayLikeWithDataType( out, 'float32' ), true, 'returns expected value' );
	t.strictEqual( out.length, 1, 'returns expected value' );
	t.strictEqual( isSameFloat32Array( getData( out ), new Float32Array( buf, 0, 1 ) ), true, 'returns expected value' );

	t.end();
});

